import React, { useEffect, useState } from 'react';
import './Carrito.css';
import NavMenu from '../../navMenu/NavMenu';
import Loading from '../../loading/Loading';
import { FaTrash } from 'react-icons/fa';
import { getCartItems, removeFromCart, updateCartItemQuantity } from '../Carrito_Localstorang/CaritoLocalstorang';
import { setUserData, getUserData } from '../../Usuario/LocalStorangUser/LocalstorangUser';
import { Compra, Buscar_Tienda, Create_Order, LogalstorangUSER } from '../../../Redux/Actions/Usuario/Action-user';
import { useDispatch, useSelector } from 'react-redux';
import alertify from 'alertifyjs';
import 'alertifyjs/build/css/alertify.css';
import { useNavigate } from 'react-router-dom';

const Carrito = () => {
  const user = useSelector((state) => state.USER);
  const [loading, setLoading] = useState(true);
  const [cartItems, setCartItems] = useState([]);
  const [order, setOrder] = useState(false);
  const [urlcompras, setUrlcompras] = useState('');
  const [groupedItems, setGroupedItems] = useState({});
  const [tiendasData, setTiendasData] = useState({});
  const dispatch = useDispatch();
  const navigate = useNavigate();

  useEffect(() => {
    const storedUser = getUserData();

    if (!user || user.state === "false") {
      if (!storedUser || storedUser.state === "false") {
        navigate('/');
      } else {
        dispatch(LogalstorangUSER(storedUser));
      }
    } else {
      setUserData(user);
    }
  }, [navigate, user, dispatch]);

  useEffect(() => {
    const timer = setTimeout(() => {
      setLoading(false);
    }, 3000);

    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    const items = getCartItems();
    setCartItems(items);
  }, []);

  const handleRemoveItem = (id) => {
    removeFromCart(id);
    const updatedCartItems = getCartItems();
    setCartItems(updatedCartItems);
    // Actualizar en Redux si es necesario
  };

  const handleUpdateQuantity = (id, quantity) => {
    updateCartItemQuantity(id, quantity);
    const updatedCartItems = getCartItems();
    setCartItems(updatedCartItems);
    // Actualizar en Redux si es necesario
  };

  const calculateTotal = () => {
    return cartItems.reduce((total, item) => total + item.costo * item.quantity, 0);
  };

  const handleCrearOrden = async () => {
    try {
      const grouped = cartItems.reduce((acc, item) => {
        if (!acc[item.tienda]) {
          acc[item.tienda] = [];
        }
        acc[item.tienda].push(item);
        return acc;
      }, {});

      setGroupedItems(grouped);

      for (const [tienda, items] of Object.entries(grouped)) {
        const totalCost = items.reduce((total, item) => total + item.costo * item.quantity, 0);
        const cantidad = items.reduce((total, item) => total + item.quantity, 0);
        const descriptions = items.map(item => item.descripcion).join(', ');

        if (!tiendasData[tienda]) {
          const data = await dispatch(Buscar_Tienda(tienda));
          setTiendasData(prevState => ({
            ...prevState,
            [tienda]: data
          }));
        }

        const compra = await dispatch(Compra(descriptions, cantidad, totalCost, tiendasData[tienda]));
        setUrlcompras(compra);
        const order = await dispatch(Create_Order(tienda, compra, items, totalCost, 'false', 'Registrada'));

        alertify.alert('Orden creada', `Orden para la tienda ${tiendasData[tienda]} creada correctamente. ID de compra: ${compra}`);
      }

      setOrder(true);
    } catch (error) {
      console.error(error);
      alertify.alert('Error', 'No se pudo crear la preferencia de pago.');
    }
  };

  return (
    <div>
      {loading && <Loading />}
      <NavMenu className="nav-menu" />
      <div className="CarritoBody">
        <div className="Carrito-cards">
          <div className="Carrito-cards-titulo">
            <h1>Carrito de Compras</h1>
          </div>
          <div className="grup-generl-cart">
            <div className="Carrito-cards-contenido">
              {cartItems.length === 0 ? (
                <div className="no-items-message">No hay elementos en el carrito</div>
              ) : order === false ? (
                cartItems.map(item => (
                  <div key={item.id} className="carrito-item-genmeral">
                    <img src={item.url} alt="Imagen del item para venta" className="carrito-imagen-item" />
                    <div className="item-card-conmtenido">{item.descripcion}</div>
                    <div className="grub-botones-carrito">
                      <div className="item-card-conmtenido">
                        <div className="btn-carrito" onClick={() => handleRemoveItem(item.id)}>
                          <FaTrash />
                        </div>
                      </div>
                      <div className="btn-carrito" onClick={() => handleUpdateQuantity(item.id, item.quantity - 1)}>
                        -
                      </div>
                      <div className="item-card-conmtenido">
                        <input type="text" className="input-carrito" value={item.quantity} readOnly />
                      </div>
                      <div className="btn-carrito" onClick={() => handleUpdateQuantity(item.id, item.quantity + 1)}>
                        +
                      </div>
                    </div>
                    <div className="item-card-conmtenido">Costo: ${item.costo * item.quantity}</div>
                  </div>
                ))
              ) : (
                <>
                  <h1>Órdenes Desarrolladas</h1>
                  <table className="orders-table">
                    <thead>
                      <tr>
                        <th>Tienda</th>
                        <th>Items</th>
                        <th>Costo Total Tienda</th>
                        <th>Acciones</th>
                      </tr>
                    </thead>
                    <tbody>
                      {Object.entries(groupedItems).map(([tienda, items]) => (
                        <tr key={tienda}>
                          <td>{tiendasData[tienda]}</td>
                          <td>
                            <div className='text-flex-columns'>
                              {items.map((item, index) => (
                                <div key={index}>{item.descripcion}</div>
                              ))}
                            </div>
                          </td>
                          <td>${items.reduce((total, item) => total + item.costo * item.quantity, 0)}</td>
                          <td>
                            <button className="MercadoPago-button" onClick={() => window.open(urlcompras)}>
                              Pago con Mercado Pago Tienda {tiendasData[tienda]}
                            </button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </>
              )}
            </div>
          </div>
          {order === false ? (
            <div className="crear-orden-carrito">
              <div className="item-card-pagar">Total a Pagar</div>
              <div className="item-card-pagar">Costo: ${calculateTotal()}</div>
              <div className="item-card-pagar">
                <div className="btn-carrito-order" onClick={handleCrearOrden}>Crear Orden</div>
              </div>
            </div>
          ) : (
            <div className="crear-orden-carrito">
              <div className="item-card-pagar"></div>
              <div className="item-card-pagar"></div>
              <div className="item-card-pagar">
                <div className="btn-carrito-order">Cancelar Orden</div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Carrito;
